"""Minimal dict-based ECS with deterministic JSON snapshots.

Entities are integer ids mapping to dicts of ``component_name -> component data``
(component data is itself a plain dict).  ``save`` serializes a world to bytes
such that the output depends only on the world's *structure*, not on the
accidental entity ids assigned during play:

* entity ids are remapped to a canonical dense order (sorted by original id),
* keys are sorted, separators are compact -> save(load(save(w))) == save(w).
"""

from __future__ import annotations

import json

KNOWN_COMPONENTS = frozenset({"Position", "Health", "Inventory"})


class UnknownComponentError(ValueError):
    """Raised when a snapshot (or add_component call) names an unknown component."""


class World:
    def __init__(self) -> None:
        self._next_id = 0
        self.entities: dict[int, dict[str, dict]] = {}

    # -- entity management -------------------------------------------------
    def create_entity(self) -> int:
        eid = self._next_id
        self._next_id += 1
        self.entities[eid] = {}
        return eid

    def destroy_entity(self, eid: int) -> None:
        del self.entities[eid]

    # -- components --------------------------------------------------------
    def add_component(self, eid: int, name: str, data: dict) -> None:
        if name not in KNOWN_COMPONENTS:
            raise UnknownComponentError(f"unknown component type: {name!r}")
        self.entities[eid][name] = dict(data)

    def has_component(self, eid: int, name: str) -> bool:
        return name in self.entities[eid]

    def get_component(self, eid: int, name: str) -> dict:
        return self.entities[eid][name]


def _remap_inventory(data: dict, id_map: dict[int, int]) -> dict:
    """Rewrite entity-id links inside an Inventory component."""
    out = dict(data)
    if "items" in out:
        try:
            out["items"] = [id_map[int(i)] for i in out["items"]]
        except KeyError as exc:
            raise ValueError(
                f"Inventory references entity {exc.args[0]} which does not exist"
            ) from None
    return out


def save(world: World) -> bytes:
    """Serialize *world* to canonical JSON bytes.

    Entities appear in dense canonical order 0..n-1, assigned by sorting their
    current ids; every entity-id reference inside Inventory is remapped to the
    same canonical ids.
    """
    order = sorted(world.entities)
    id_map = {old: new for new, old in enumerate(order)}

    doc: dict[str, dict] = {}
    for old in order:
        comps: dict[str, dict] = {}
        for name, data in world.entities[old].items():
            if name == "Inventory":
                comps[name] = _remap_inventory(data, id_map)
            else:
                comps[name] = dict(data)
        doc[str(id_map[old])] = comps

    return json.dumps(doc, sort_keys=True, separators=(",", ":")).encode("utf-8")


def load(payload: bytes) -> World:
    """Rebuild a world from ``save`` output. Entity ids are dense from 0."""
    try:
        doc = json.loads(payload.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"snapshot is not valid JSON: {exc}") from None
    if not isinstance(doc, dict):
        raise ValueError("snapshot root must be a JSON object")

    world = World()
    for key in sorted(doc, key=lambda k: int(k)):
        eid = world.create_entity()  # dense ids: 0, 1, 2, ...
        raw_comps = doc[key]
        if not isinstance(raw_comps, dict):
            raise ValueError(f"entity {eid}: component set must be an object")
        for name, data in sorted(raw_comps.items()):
            if name not in KNOWN_COMPONENTS:
                raise UnknownComponentError(f"unknown component type: {name!r}")
            if not isinstance(data, dict):
                raise ValueError(f"entity {eid}: component {name!r} must be an object")
            if name == "Inventory":
                items = data.get("items", [])
                if not isinstance(items, list) or not all(
                    isinstance(i, int) and 0 <= i < len(doc) for i in items
                ):
                    raise ValueError(
                        f"entity {eid}: Inventory.items must link to existing entities"
                    )
            world.add_component(eid, name, data)
    return world

