def _canonical_order(world: World) -> list[int]:
    """Order entity ids canonically from world structure.

    Starts from an id-independent fingerprint of each entity's components
    (Inventory reduced to its arity), then repeatedly refines fingerprints
    with the fingerprints of linked entities until stable.  Sorting by the
    resulting fingerprint yields the same dense order for any two worlds
    that are equal up to entity relabeling.
    """

    def fingerprint(eid: int, link_ranks: dict[int, str]) -> str:
        comps = {}
        for name, data in world.entities[eid].items():
            if name == "Inventory":
                comps[name] = {
                    "items": sorted(link_ranks[i] for i in data.get("items", []))
                }
            else:
                comps[name] = data
        return json.dumps(comps, sort_keys=True)

    ranks = {eid: "" for eid in world.entities}
    keys = {eid: fingerprint(eid, ranks) for eid in world.entities}
    for _ in range(max(1, len(world.entities))):
        new_keys = {eid: fingerprint(eid, keys) for eid in world.entities}
        if sorted(new_keys.values()) == sorted(keys.values()):
            break
        keys = new_keys
    return sorted(world.entities, key=lambda e: keys[e])


