    """Serialize *world* to canonical JSON bytes.

    Entities appear in dense canonical order 0..n-1 (see ``_canonical_order``);
    every entity-id reference inside Inventory is remapped to the same
    canonical ids.
    """
    order = _canonical_order(world)
    id_map = {old: new for new, old in enumerate(order)}

